import{_ as a}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as t,c as s,a as i}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const b=JSON.parse(`{"title":"What's new in v1.11.0","description":"Team pick mode and --exclude-template-repositories — resolve multi-team sections interactively or via CLI, and filter template repos from search results.","frontmatter":{"title":"What's new in v1.11.0","description":"Team pick mode and --exclude-template-repositories — resolve multi-team sections interactively or via CLI, and filter template repos from search results.","date":"2026-03-30T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v1-11-0.md","filePath":"blog/release-v1-11-0.md"}`),o={name:"blog/release-v1-11-0.md"};function n(r,e,l,d,h,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="what-s-new-in-github-code-search-v1-11-0" tabindex="-1">What&#39;s new in github-code-search v1.11.0 <a class="header-anchor" href="#what-s-new-in-github-code-search-v1-11-0" aria-label="Permalink to &quot;What&#39;s new in github-code-search v1.11.0&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v1.11.0" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v1.11.0</a></p></blockquote><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="team-pick-mode-—-resolve-multi-team-ownership-interactively" tabindex="-1">Team pick mode — resolve multi-team ownership interactively <a class="header-anchor" href="#team-pick-mode-—-resolve-multi-team-ownership-interactively" aria-label="Permalink to &quot;Team pick mode — resolve multi-team ownership interactively&quot;">​</a></h3><p>When using <code>--group-by-team-prefix</code>, repositories that belong to <strong>multiple teams</strong> appear under combined section headers such as <code>squad-frontend + squad-mobile</code>. In v1.11.0, you can now resolve these ambiguous sections in real time from the TUI.</p><p>Navigate to a combined section header and press <strong><code>p</code></strong> to enter pick mode. The header turns into a horizontal picker:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>── [ squad-frontend ]  squad-mobile</span></span></code></pre></div><p>The highlighted team (bold, wrapped in <code>[ ]</code>) is the current candidate. Navigate sideways and confirm your choice:</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>←</code> / <code>→</code></td><td>Move focus between candidate teams</td></tr><tr><td><code>Enter</code></td><td>Confirm — section label updates in place</td></tr><tr><td><code>Esc</code></td><td>Cancel — no change</td></tr></tbody></table><p>Repos moved by pick mode are annotated with a <strong><code>◈</code></strong> badge so you can track assignments at a glance.</p><h3 id="pick-team-—-pre-assign-sections-without-the-tui" tabindex="-1"><code>--pick-team</code> — pre-assign sections without the TUI <a class="header-anchor" href="#pick-team-—-pre-assign-sections-without-the-tui" aria-label="Permalink to &quot;`--pick-team` — pre-assign sections without the TUI&quot;">​</a></h3><p>Assignments can also be made up front with the repeatable <code>--pick-team</code> option — useful in CI or when replaying a previous run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> query</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --group-by-team-prefix</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> squad-</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --pick-team</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;squad-frontend + squad-mobile&quot;=squad-frontend</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --pick-team</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;squad-backend + squad-data&quot;=squad-backend</span></span></code></pre></div><p>The replay command printed at the top of the markdown output now includes <code>--pick-team</code> flags automatically when picks were confirmed interactively, so <strong>every run is fully reproducible</strong>.</p><p>If a combined label is not found (typo, stale label), a warning is emitted on stderr listing the available sections — the run continues without error.</p><h3 id="exclude-template-repositories-—-clean-up-template-noise" tabindex="-1"><code>--exclude-template-repositories</code> — clean up template noise <a class="header-anchor" href="#exclude-template-repositories-—-clean-up-template-noise" aria-label="Permalink to &quot;`--exclude-template-repositories` — clean up template noise&quot;">​</a></h3><p>GitHub template repositories often appear in search results even when they are not the target of the search (e.g. a boilerplate that was never extended). A new flag lets you exclude them entirely:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --exclude-template-repositories</span></span></code></pre></div><p>Template repos are identified using the <code>is_template</code> field returned by the GitHub API — no additional token scope is required. The flag is also recorded in the replay command so non-interactive reruns are consistent.</p><h3 id="security-improvements" tabindex="-1">Security improvements <a class="header-anchor" href="#security-improvements" aria-label="Permalink to &quot;Security improvements&quot;">​</a></h3><p>This release also ships <strong>hardened implementations</strong> of the <code>cache</code> and <code>upgrade</code> modules, guided by an Aikido security scan:</p><ul><li>Path inputs are now validated before any filesystem operations.</li><li>The upgrade path uses a safer temporary-file write strategy.</li><li>A <code>dependabot.yml</code> is now in place to keep GitHub Actions dependencies up to date.</li></ul><h3 id="windows-installer-fixes-patch" tabindex="-1">Windows installer fixes (patch) <a class="header-anchor" href="#windows-installer-fixes-patch" aria-label="Permalink to &quot;Windows installer fixes (patch)&quot;">​</a></h3><p>The PowerShell installer (<code>install.ps1</code>) now:</p><ul><li>Avoids the <code>Invoke-WebRequest</code> security warning that appeared on default Windows security configurations.</li><li>Falls back to <code>curl.exe</code> (bundled with Windows 10+) when the GitHub API is unreachable for a specific version lookup.</li></ul><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Or download the latest binary from <a href="https://github.com/fulll/github-code-search/releases/tag/v1.11.0" target="_blank" rel="noreferrer">GitHub Releases</a>.</p>',29)])])}const y=a(o,[["render",n]]);export{b as __pageData,y as default};
